/* ===== PS01-W32 结构观感（v3.42.0，随深浅主题）===== */
/* 经典 3D：全直角 + 凸起边框（亮上左 / 暗下右）*/
QToolButton {
  border-radius: 0;
  border: 1px solid {btn_border};
  border-top-color: {btn_light};
  border-left-color: {btn_light};
  background: {btn_bg};
}
QToolButton:hover {
  background: {btn_hover_bg};
}
QToolButton:pressed {
  border-top-color: {btn_shadow};
  border-left-color: {btn_shadow};
  border-bottom-color: {btn_light};
  border-right-color: {btn_light};
  background: {btn_pressed};
}
QMenu {
  border-radius: 0;
  border: 1px solid {btn_shadow};
}
QMenu::item {
  border-radius: 0;
}
QMenu::item:selected {
  background: {menu_hover_bg};
  color: {menu_sel_text};
}
QMainWindow #tabstrip QTabBar::tab:!selected {
  border-radius: 0;
  border: 1px solid {tab_border};
  border-bottom: none;
}
QMainWindow #tabstrip QTabBar::tab:selected {
  background: {tab_sel_bg};
  border-top: 2px solid {accent};
}
QLineEdit, QComboBox {
  border-radius: 0;
}
